"""V3 uint8 memmap cache shard builder (Kaggle CPU, internet off). Generated by build.py.

Output (/kaggle/working): slices.npy [total,256,256] uint8 (np.lib.format), index.csv (one row
per train_series.csv series of this shard's studies), summary.json, checksums.sha256.
Studies are assigned by sha256(StudyInstanceUID) % NSHARD. Nothing is excluded from caching;
partition/exclude columns come from the frozen dev split (excluded = 58 expert + 7 linked).
"""
import csv
import collections
import hashlib
import json
import os
import sys
import time
from concurrent.futures import ProcessPoolExecutor, as_completed
from pathlib import Path

import numpy as np

SHARD, NSHARD, PILOT = 1, 5, False
SOURCES = {'m00_data.py': '"""M00 data path: series selection, DICOM ordering/scaling, window sampling, study tensor.\n\nOffline, deterministic, no flips. Failures raise SeriesError (series-level) or StudyError\n(study-level) so callers can count them; nothing is silently substituted.\n"""\nimport numpy as np\nimport torch\nimport torch.nn.functional as F\n\nROLES = ("Sagittal", "Coronal", "Axial")\nTRAIN_WINDOWS, INFER_WINDOWS, SIZE = 4, 16, 224\nTOL_MM = 1e-3\n\n\nclass SeriesError(ValueError):\n    pass\n\n\nclass StudyError(ValueError):\n    pass\n\n\ndef select_series(rows):\n    """rows: iterable of dicts with SeriesInstanceUID, Fluid_Sensitive, Fat_Suppression,\n    Anatomical_Plane (official train_series.csv fields) for ONE study.\n    Returns {role: SeriesInstanceUID or None}. Deterministic.\n    ponytail: preference fluid-sensitive > fat-suppressed > smallest UID is MY choice, not a\n    clinical rule; revisit after the A05 role study."""\n    best = {r: None for r in ROLES}\n    for row in rows:\n        role = str(row["Anatomical_Plane"]).strip().capitalize()\n        if role not in best:\n            continue\n        key = (-int(row["Fluid_Sensitive"] or 0), -int(row["Fat_Suppression"] or 0),\n               str(row["SeriesInstanceUID"]))\n        if best[role] is None or key < best[role][0]:\n            best[role] = (key, str(row["SeriesInstanceUID"]))\n    return {r: (v[1] if v else None) for r, v in best.items()}\n\n\ndef slice_position(ds):\n    """Projection of ImagePositionPatient on row x col normal; None if tags missing."""\n    iop, ipp = getattr(ds, "ImageOrientationPatient", None), getattr(ds, "ImagePositionPatient", None)\n    if iop is None or ipp is None:\n        return None\n    iop, ipp = np.asarray(iop, float), np.asarray(ipp, float)\n    if iop.shape != (6,) or ipp.shape != (3,) or not (np.isfinite(iop).all() and np.isfinite(ipp).all()):\n        raise SeriesError("malformed orientation/position tags")\n    r, c = iop[:3], iop[3:]\n    if abs(np.linalg.norm(r) - 1) > 1e-2 or abs(np.linalg.norm(c) - 1) > 1e-2 or abs(r @ c) > 1e-2:\n        raise SeriesError("ImageOrientationPatient not orthonormal")\n    return float(ipp @ np.cross(r, c)), tuple(np.round(np.cross(r, c), 3))\n\n\ndef order_slices(datasets):\n    """Sort datasets by physical position. Fallback to InstanceNumber ONLY if every slice lacks\n    orientation/position tags; mixed presence, duplicates, irregular gaps or in-plane changes raise."""\n    if not datasets:\n        raise SeriesError("empty series")\n    spacings = []\n    for ds in datasets:\n        raw = getattr(ds, "PixelSpacing", None)\n        if raw is None:\n            raise SeriesError("missing PixelSpacing")\n        spacing = np.asarray(raw, dtype=float)\n        if spacing.shape != (2,) or not np.isfinite(spacing).all() or np.any(spacing <= 0):\n            raise SeriesError("invalid PixelSpacing")\n        spacings.append(spacing)\n    if any(np.max(np.abs(spacing - spacings[0])) > 1e-3 for spacing in spacings[1:]):\n        raise SeriesError("pixel spacing differs within series")\n    pos = [slice_position(d) for d in datasets]\n    if all(p is None for p in pos):\n        nums = [getattr(d, "InstanceNumber", None) for d in datasets]\n        if any(n is None for n in nums) or len(set(int(n) for n in nums)) != len(nums):\n            raise SeriesError("no geometry tags and InstanceNumber missing/duplicated")\n        keys = [float(n) for n in nums]\n    elif any(p is None for p in pos):\n        raise SeriesError("geometry tags present on only some slices")\n    else:\n        if len({p[1] for p in pos}) != 1:\n            raise SeriesError("slice normal differs within series")\n        orientation = np.asarray(datasets[0].ImageOrientationPatient, dtype=float)\n        if any(np.max(np.abs(np.asarray(ds.ImageOrientationPatient, dtype=float) - orientation)) > 1e-3\n               for ds in datasets[1:]):\n            raise SeriesError("in-plane orientation differs within series")\n        keys = [p[0] for p in pos]\n    order = np.argsort(keys, kind="stable")\n    s = np.asarray(keys)[order]\n    if len(s) > 1 and np.diff(s).min() < TOL_MM:\n        raise SeriesError("duplicate slice positions")\n    if len(s) > 2:\n        gaps = np.diff(s)\n        if gaps.max() > 1.5 * np.median(gaps) + 0.01:\n            raise SeriesError("irregular slice gap")\n    return [datasets[i] for i in order]\n\n\ndef slice_pixels(ds):\n    """float32 pixels after rescale and MONOCHROME1 inversion (negation; scaling is affine)."""\n    a = ds.pixel_array.astype(np.float32)\n    if a.ndim != 2:\n        raise SeriesError("non-2D pixel array")\n    a = a * float(getattr(ds, "RescaleSlope", 1.0)) + float(getattr(ds, "RescaleIntercept", 0.0))\n    if str(getattr(ds, "PhotometricInterpretation", "MONOCHROME2")) == "MONOCHROME1":\n        a = -a\n    return a\n\n\ndef load_series(datasets, lo_q=1.0, hi_q=99.0):\n    """-> (volume [N,H,W] float32 in [0,1], slice_ok [N] bool). Slices with nonfinite values or\n    constant content are flagged not-ok (zero-filled, never used in a window)."""\n    ds = order_slices(datasets)\n    arrs = [slice_pixels(d) for d in ds]\n    if len({a.shape for a in arrs}) != 1:\n        raise SeriesError("inconsistent slice shapes")\n    ok = np.array([np.isfinite(a).all() and a.max() > a.min() for a in arrs])\n    if ok.sum() < 3:\n        raise SeriesError("fewer than 3 usable slices")\n    # Bound percentile scratch memory for large series while sampling each slice\n    # deterministically. Full decoded slices are still used for final scaling.\n    vals = np.concatenate([\n        a.ravel()[::max(1, a.size // 16384)] for a, k in zip(arrs, ok) if k\n    ])\n    lo, hi = np.percentile(vals, [lo_q, hi_q])\n    if not hi > lo:\n        raise SeriesError("degenerate intensity range")\n    vol = np.stack([np.clip((a - lo) / (hi - lo), 0, 1) if k else np.zeros_like(a)\n                    for a, k in zip(arrs, ok)]).astype(np.float32)\n    return vol, ok\n\n\ndef window_centers(ok, n, rng=None):\n    """Centers c such that slices c-1,c,c+1 are all usable (physically adjacent in sorted order).\n    rng None -> deterministic evenly spaced (inference); else random without replacement (train)."""\n    valid = np.flatnonzero(ok[:-2] & ok[1:-1] & ok[2:]) + 1\n    if len(valid) == 0:\n        return valid\n    if rng is None:\n        return np.unique(valid[np.round(np.linspace(0, len(valid) - 1, n)).astype(int)])\n    return np.sort(rng.choice(valid, size=min(n, len(valid)), replace=False))\n\n\ndef series_windows(vol, ok, n, rng=None):\n    """-> (x [n,3,224,224], mask [n]); unused rows zero with mask False."""\n    x = torch.zeros(n, 3, SIZE, SIZE)\n    m = torch.zeros(n, dtype=torch.bool)\n    for i, c in enumerate(window_centers(ok, n, rng)):\n        w = torch.from_numpy(vol[c - 1:c + 2])[None]\n        x[i] = F.interpolate(w, size=(SIZE, SIZE), mode="bilinear", align_corners=False)[0]\n        m[i] = True\n    return x, m\n\n\ndef build_study(role_series, train, rng=None):\n    """role_series: {role: (vol, ok) or None}. -> (x [3,W,3,224,224], mask [3,W]).\n    Raises StudyError if no role yields a valid window."""\n    n = TRAIN_WINDOWS if train else INFER_WINDOWS\n    xs, ms = [], []\n    for r in ROLES:\n        s = role_series.get(r)\n        x, m = series_windows(*s, n, rng if train else None) if s else (\n            torch.zeros(n, 3, SIZE, SIZE), torch.zeros(n, dtype=torch.bool))\n        xs.append(x), ms.append(m)\n    mask = torch.stack(ms)\n    if not mask.any():\n        raise StudyError("study has no valid window in any role")\n    return torch.stack(xs), mask\n', 'canon.py': '"""V3 canonical series preprocessing, shared by the cache builder and offline inference.\n\ncanon_series(datasets or paths) -> (uint8 [N,256,256], meta):\n  IPP-projected slice order (m00_data.order_slices), slices ascending along +LPS axis of the\n  dominant normal; in-plane flips/transposes only (no interpolation) so that\n    sagittal: cols -> +y (posterior), rows -> -z (inferior)\n    coronal:  cols -> +x (patient left), rows -> -z\n    axial:    cols -> +x, rows -> +y\n  160 mm physical square centre crop/pad, antialiased area resize to 256 px (0.625 mm/px),\n  foreground (Otsu) p0.5-p99.8 -> uint8. Laterality is only reported (meta), never applied.\n"""\nimport numpy as np\nimport torch\nimport torch.nn.functional as F\n\nfrom m00_data import SeriesError, order_slices, slice_pixels, slice_position\n\nOUT_PX, CROP_MM, LO_Q, HI_Q, LAT_MM = 256, 160.0, 0.5, 99.8, 20.0\nAXES = np.eye(3)\n# normal axis -> (target col direction, target row direction) in LPS\nTARGETS = {0: (AXES[1], -AXES[2]), 1: (AXES[0], -AXES[2]), 2: (AXES[0], AXES[1])}\nPLANE = {0: "Sagittal", 1: "Coronal", 2: "Axial"}\n\n\ndef _otsu(v):\n    hist, edges = np.histogram(v, 256)\n    c = (edges[:-1] + edges[1:]) / 2\n    w0 = np.cumsum(hist).astype(float)\n    w1 = w0[-1] - w0\n    s0 = np.cumsum(hist * c)\n    with np.errstate(divide="ignore", invalid="ignore"):\n        var = w0 * w1 * (s0 / w0 - (s0[-1] - s0) / w1) ** 2\n    return c[int(np.nanargmax(var[:-1]))]\n\n\ndef _fit(a, n, axis, fill):\n    """Centre crop or symmetric pad `a` to length n along axis."""\n    h = a.shape[axis]\n    if h < n:\n        pad = [(0, 0)] * a.ndim\n        pad[axis] = ((n - h) // 2, n - h - (n - h) // 2)\n        return np.pad(a, pad, constant_values=fill)\n    s = (h - n) // 2\n    return a[(slice(None),) * axis + (slice(s, s + n),)]\n\n\ndef _laterality(ds, r, c, sp):\n    for tag in ("Laterality", "ImageLaterality"):\n        v = str(getattr(ds, tag, "") or "").strip().upper()[:1]\n        if v in ("L", "R"):\n            return v, "tag", float("nan")\n    ctr = (np.asarray(ds.ImagePositionPatient, float) + r * sp[1] * (int(ds.Columns) - 1) / 2\n           + c * sp[0] * (int(ds.Rows) - 1) / 2)\n    x = float(ctr[0])\n    return ("L" if x > LAT_MM else "R" if x < -LAT_MM else "U"), "ipp_x", x\n\n\ndef canon_series(datasets):\n    if datasets and not hasattr(datasets[0], "pixel_array"):\n        import pydicom\n        datasets = [pydicom.dcmread(str(p)) for p in datasets]\n    ds = order_slices(datasets)\n    if slice_position(ds[0]) is None:\n        raise SeriesError("no orientation tags; cannot canonicalise")\n    iop = np.asarray(ds[0].ImageOrientationPatient, float)\n    r0, c0 = iop[:3], iop[3:]\n    n = np.cross(r0, c0)\n    ax = int(np.argmax(np.abs(n)))\n    if n[ax] < 0:  # ascending along +axis\n        ds, n = ds[::-1], -n\n    pos = np.array([float(np.asarray(d.ImagePositionPatient, float) @ n) for d in ds])\n    sp = np.asarray(ds[0].PixelSpacing, float)  # (row spacing, col spacing)\n    lat, lat_src, ctr_x = _laterality(ds[len(ds) // 2], r0, c0, sp)\n\n    tc, tr = TARGETS[ax]\n    transpose = abs(r0 @ tc) < abs(c0 @ tc)\n    r, c = (c0, r0) if transpose else (r0, c0)\n    if transpose:\n        sp = sp[::-1]\n    flip_c, flip_r = bool(r @ tc < 0), bool(c @ tr < 0)\n    ch, cw = (int(round(CROP_MM / s)) for s in sp)\n    if len({(int(d.Rows), int(d.Columns)) for d in ds}) != 1:\n        raise SeriesError("inconsistent slice shapes")\n\n    out, bad = [], 0\n    for d in ds:\n        a = slice_pixels(d)\n        if not np.isfinite(a).all() or a.max() <= a.min():\n            bad += 1\n            a = np.nan_to_num(a, nan=0.0, posinf=0.0, neginf=0.0)\n        if transpose:\n            a = a.T\n        a = a[::-1 if flip_r else 1, ::-1 if flip_c else 1]\n        fill = float(a.min())\n        a = _fit(_fit(a, ch, 0, fill), cw, 1, fill)\n        t = torch.from_numpy(np.ascontiguousarray(a, dtype=np.float32))[None, None]\n        mode = "area" if min(ch, cw) >= OUT_PX else "bilinear"\n        out.append(F.interpolate(t, size=(OUT_PX, OUT_PX), mode=mode,\n                                 **({"align_corners": False} if mode == "bilinear" else {}))[0, 0].numpy())\n    vol = np.stack(out)\n    v = vol.ravel()[:: max(1, vol.size // 2_000_000)]\n    fg = v[v > _otsu(v)]\n    if fg.size < 0.01 * v.size:\n        fg = v\n    lo, hi = (float(x) for x in np.percentile(fg, [LO_Q, HI_Q]))\n    if not hi > lo:  # flat foreground: fall back to all pixels\n        lo, hi = (float(x) for x in np.percentile(v, [LO_Q, HI_Q]))\n    if not hi > lo:\n        raise SeriesError("degenerate intensity range")\n    img = np.round(np.clip((vol - lo) / (hi - lo), 0, 1) * 255).astype(np.uint8)\n    meta = {\n        "plane_geom": PLANE[ax], "n": len(ds), "positions": pos.tolist(),\n        "row_spacing": float(sp[0]), "col_spacing": float(sp[1]),\n        "thickness": float(getattr(ds[0], "SliceThickness", None) or "nan"),\n        "laterality": lat, "laterality_source": lat_src, "centre_x_mm": ctr_x,\n        "lo": lo, "hi": hi, "transpose": bool(transpose), "flip_rows": flip_r, "flip_cols": flip_c,\n        "bad_slices": bad, "orig_shape": (int(ds[0].Rows), int(ds[0].Columns)),\n    }\n    return img, meta\n'}
SRC = Path("/tmp/v3src")
SRC.mkdir(parents=True, exist_ok=True)
for name, text in SOURCES.items():
    (SRC / name).write_text(text, encoding="utf-8")
sys.path.insert(0, str(SRC))
from canon import OUT_PX, canon_series  # noqa: E402

COMP = next(p for p in (Path("/kaggle/input/competitions/rsna-knee-abnormality-detection"),
                        Path("/kaggle/input/rsna-knee-abnormality-detection")) if p.is_dir())
SPLIT = next(p for p in (Path("/kaggle/input/rsna-knee-v2-frozen-dev-split/split.csv"),
                         Path("/kaggle/input/datasets/aymenslimani/rsna-knee-v2-frozen-dev-split/split.csv"))
             if p.is_file())
OUT = Path("/kaggle/working")
NPY = OUT / "slices.npy"
MAX_BYTES = 18.5 * 2**30


def h(uid):
    return int(hashlib.sha256(uid.encode()).hexdigest()[:8], 16)


def paths_of(row):
    return sorted((COMP / "train_series" / row["StudyInstanceUID"] / row["SeriesInstanceUID"]).glob("*.dcm"))


def init():
    import torch
    torch.set_num_threads(1)


def work(i, row, start, count):
    t0 = time.time()
    try:
        x, m = canon_series(paths_of(row))
        if len(x) != count:
            raise ValueError(f"slice count {len(x)} != files {count}")
        mm = np.load(NPY, mmap_mode="r+")
        mm[start:start + count] = x
        mm.flush()
        del mm
        return i, m, "", time.time() - t0
    except Exception as e:  # counted per type, never substituted
        return i, None, f"{type(e).__name__}: {e}"[:200], time.time() - t0


def sha256_file(p):
    d = hashlib.sha256()
    with open(p, "rb") as f:
        for b in iter(lambda: f.read(1 << 24), b""):
            d.update(b)
    return d.hexdigest()


def parity(rows, starts, counts, index):
    """Re-decode every ok series directly and compare with the stored cache (exact), plus an
    independent cv2 INTER_AREA path on the middle slice of each series (correlation)."""
    import cv2
    mm = np.load(NPY, mmap_mode="r")
    exact, mismatch, corrs, mads = 0, 0, [], []
    for i, row in enumerate(rows):
        if index[i]["ok"] != "1":
            continue
        cached = mm[starts[i]:starts[i] + counts[i]]
        x, m = canon_series(paths_of(row))
        same = np.array_equal(x, cached) and np.allclose(
            m["positions"], [float(v) for v in index[i]["positions"].split(";")], atol=1e-3)
        exact += same
        mismatch += not same
        # independent path: raw DICOM -> geometry from stored flags -> crop -> cv2 area -> lo/hi
        import pydicom
        dss = [pydicom.dcmread(str(p)) for p in paths_of(row)]
        nvec = np.cross(*np.asarray(dss[0].ImageOrientationPatient, float).reshape(2, 3))
        ax = int(np.argmax(np.abs(nvec)))
        key = [float(np.asarray(d.ImagePositionPatient, float) @ nvec) * np.sign(nvec[ax]) for d in dss]
        d = dss[int(np.argsort(key)[len(dss) // 2])]
        a = d.pixel_array.astype(np.float32) * float(getattr(d, "RescaleSlope", 1)) + float(getattr(d, "RescaleIntercept", 0))
        if index[i]["transpose"] == "1":
            a = a.T
        a = a[::-1 if index[i]["flip_rows"] == "1" else 1, ::-1 if index[i]["flip_cols"] == "1" else 1]
        ch, cw = round(160 / float(index[i]["row_spacing"])), round(160 / float(index[i]["col_spacing"]))
        H, W = a.shape
        big = np.full((max(H, ch), max(W, cw)), a.min(), np.float32)
        big[(big.shape[0] - H) // 2:(big.shape[0] - H) // 2 + H, (big.shape[1] - W) // 2:(big.shape[1] - W) // 2 + W] = a
        r0, c0 = (big.shape[0] - ch) // 2, (big.shape[1] - cw) // 2
        crop = np.ascontiguousarray(big[r0:r0 + ch, c0:c0 + cw])
        res = cv2.resize(crop, (OUT_PX, OUT_PX), interpolation=cv2.INTER_AREA if min(ch, cw) >= OUT_PX else cv2.INTER_LINEAR)
        lo, hi = float(index[i]["lo"]), float(index[i]["hi"])
        ref = np.clip((res - lo) / (hi - lo), 0, 1) * 255
        got = cached[len(dss) // 2].astype(np.float32)
        corrs.append(float(np.corrcoef(ref.ravel(), got.ravel())[0, 1]))
        mads.append(float(np.abs(ref - got).mean()))
    return {"series_checked": exact + mismatch, "exact_match": int(exact), "mismatch": int(mismatch),
            "indep_corr_min": min(corrs) if corrs else None, "indep_corr_median": float(np.median(corrs)) if corrs else None,
            "indep_mad_uint8_median": float(np.median(mads)) if mads else None, "indep_mad_uint8_max": max(mads) if mads else None}


def main():
    t_start = time.time()
    with open(COMP / "train_series.csv", newline="", encoding="utf-8") as f:
        all_rows = list(csv.DictReader(f))
    with open(SPLIT, newline="", encoding="utf-8") as f:
        part = {r["StudyInstanceUID"]: r["partition"] for r in csv.DictReader(f)}
    studies = sorted({r["StudyInstanceUID"] for r in all_rows})
    mine = set(sorted(studies, key=h)[:20]) if PILOT else {s for s in studies if h(s) % NSHARD == SHARD}
    rows = sorted((r for r in all_rows if r["StudyInstanceUID"] in mine),
                  key=lambda r: (r["StudyInstanceUID"], r["SeriesInstanceUID"]))
    counts = [len(paths_of(r)) for r in rows]
    starts = np.concatenate([[0], np.cumsum(counts)[:-1]]).astype(int).tolist()
    total = int(sum(counts))
    nbytes = total * OUT_PX * OUT_PX
    print(f"shard {SHARD}/{NSHARD} pilot={PILOT}: {len(mine)} studies, {len(rows)} series, {total} slices, {nbytes / 2**30:.2f} GiB", flush=True)
    if nbytes > MAX_BYTES:
        raise SystemExit(f"shard too large: {nbytes / 2**30:.2f} GiB")
    mm = np.lib.format.open_memmap(NPY, mode="w+", dtype=np.uint8, shape=(total, OUT_PX, OUT_PX))
    del mm

    index = [None] * len(rows)
    errors = collections.Counter()
    t0 = time.time()
    with ProcessPoolExecutor(os.cpu_count(), initializer=init) as ex:
        order = sorted(range(len(rows)), key=lambda i: -counts[i])  # big series first
        futs = [ex.submit(work, i, rows[i], starts[i], counts[i]) for i in order]
        for k, fut in enumerate(as_completed(futs)):
            i, m, err, sec = fut.result()
            r = rows[i]
            pt = part.get(r["StudyInstanceUID"], "missing")
            rec = {"study": r["StudyInstanceUID"], "series": r["SeriesInstanceUID"], "plane": r["Anatomical_Plane"],
                   "fluid": r["Fluid_Sensitive"], "fatsat": r["Fat_Suppression"], "partition": pt,
                   "exclude": int(pt not in ("candidate_train", "candidate_validation")),
                   "start": starts[i], "length": counts[i] if m else 0, "files": counts[i], "ok": int(m is not None),
                   "error": err, "seconds": round(sec, 2)}
            if m:
                rec.update({"plane_geom": m["plane_geom"], "positions": ";".join(f"{p:.3f}" for p in m["positions"]),
                            "row_spacing": m["row_spacing"], "col_spacing": m["col_spacing"], "thickness": m["thickness"],
                            "laterality": m["laterality"], "laterality_source": m["laterality_source"],
                            "centre_x_mm": m["centre_x_mm"], "lo": m["lo"], "hi": m["hi"],
                            "transpose": int(m["transpose"]), "flip_rows": int(m["flip_rows"]), "flip_cols": int(m["flip_cols"]),
                            "bad_slices": m["bad_slices"], "orig_rows": m["orig_shape"][0], "orig_cols": m["orig_shape"][1]})
            else:
                errors[err.split(":")[0]] += 1
            index[i] = rec
            if k % 200 == 0:
                print(f"{k}/{len(rows)} series, {time.time() - t0:.0f}s, errors {dict(errors)}", flush=True)
    build_s = time.time() - t0

    cols = ["study", "series", "plane", "fluid", "fatsat", "partition", "exclude", "start", "length", "files", "ok", "error",
            "plane_geom", "positions", "row_spacing", "col_spacing", "thickness", "laterality", "laterality_source",
            "centre_x_mm", "lo", "hi", "transpose", "flip_rows", "flip_cols", "bad_slices", "orig_rows", "orig_cols", "seconds"]
    with open(OUT / "index.csv", "w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, cols, restval="")
        w.writeheader()
        w.writerows(index)
    sums = {n: sha256_file(OUT / n) for n in ("slices.npy", "index.csv")}
    (OUT / "checksums.sha256").write_text("".join(f"{v}  {k}\n" for k, v in sums.items()))
    ok = [r for r in index if r["ok"]]
    summary = {
        "shard": SHARD, "nshard": NSHARD, "pilot": PILOT, "cpu_count": os.cpu_count(),
        "studies": len(mine), "series": len(rows), "series_ok": len(ok), "series_failed": len(rows) - len(ok),
        "failures_by_type": dict(errors), "slices_total": total, "slices_bytes": nbytes, "sha256": sums,
        "excluded_studies": len({r["study"] for r in index if r["exclude"]}),
        "laterality": dict(collections.Counter(f"{r['laterality']}|{r['laterality_source']}" for r in ok)),
        "build_seconds": round(build_s, 1), "seconds_per_study": round(build_s / max(1, len(mine)), 3),
    }
    if PILOT:
        tp = time.time()
        str_index = [{k: str(v) for k, v in r.items()} for r in index]
        summary["parity"] = parity(rows, starts, counts, str_index)
        summary["parity_seconds"] = round(time.time() - tp, 1)
        summary["projected_full_bytes"] = nbytes / max(1, len(mine)) * len(studies)
        summary["projected_full_cpu_hours_4core"] = build_s / max(1, len(mine)) * len(studies) / 3600
    summary["total_seconds"] = round(time.time() - t_start, 1)
    (OUT / "summary.json").write_text(json.dumps(summary, indent=1))
    print(json.dumps(summary, indent=1))


if __name__ == "__main__":
    main()
